style.css:
/* Roblox Custom Image Light Mode */
/* i really want this to be global */

:root {
  /* swap these values to customize */
  --my-image: url("https://supersonico.jp/download/wallpaper/64_2026_20th-anniv_1920x1080.jpg");
  --my-overlay: rgba(255, 255, 255, 0.18);
  --my-card: rgba(255, 255, 255, 0.78);
  --my-text: #202020;
  --my-accent: #8b5cf6;
}

/* main page background */
body {
  background-image:
    linear-gradient(var(--my-overlay), var(--my-overlay)),
    var(--my-image) !important;
  background-size: cover !important;
  background-position: center !important;
  background-attachment: fixed !important;
  background-repeat: no-repeat !important;
}

/* keep Roblox content readable */
main,
section {
  background-color: transparent !important;
}

/* cards and panels */
div[class*="card"],
div[class*="Card"],
div[class*="container"] {
  background-color: var(--my-card) !important;
  backdrop-filter: blur(8px) !important;
}

/* text */
body,
p,
span,
h1,
h2,
h3,
h4,
h5,
h6 {
  color: var(--my-text) !important;
}

/* links and accents */
a {
  color: var(--my-accent) !important;
}

/* rounded images */
img {
  border-radius: 12px !important;
}
